'use strict';

// MODULES //

var isFunction = require( '@stdlib/assert/is-function' );
var isCollection = require( '@stdlib/assert/is-collection' );
var format = require( '@stdlib/string/format' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var validate = require( './validate.js' );
var limit = require( './limit.js' );


// MAIN //

/**
* Returns a function for testing whether at least one element in a collection passes a test implemented by a predicate function.
*
* ## Notes
*
* -   If a predicate function calls the provided callback with a truthy error argument, the function suspends execution and immediately calls the `done` callback for subsequent error handling.
* -   This function does **not** guarantee that execution is asynchronous. To do so, wrap the `done` callback in a function which either executes at the end of the current stack (e.g., `nextTick`) or during a subsequent turn of the event loop (e.g., `setImmediate`, `setTimeout`).
*
* @param {Options} [options] - function options
* @param {*} [options.thisArg] - execution context
* @param {PositiveInteger} [options.limit] - maximum number of pending invocations at any one time
* @param {boolean} [options.series=false] - boolean indicating whether to wait for a previous invocation to complete before invoking a provided function for the next element in a collection
* @param {Function} predicate - predicate function to invoke for each element in a collection
* @throws {TypeError} options argument must be an object
* @throws {TypeError} must provide valid options
* @throws {TypeError} last argument must be a function
* @returns {Function} function which invokes the predicate function once for each element in a collection
*
* @example
* function predicate( value, index, next ) {
*     setTimeout( onTimeout, value );
*     function onTimeout() {
*         next( null, false );
*     }
* }
*
* var opts = {
*     'series': true
* };
*
* // Create a `anyByAsync` function which invokes the predicate function for each collection element sequentially:
* var anyByAsync = factory( opts, predicate );
*
* // Create a collection over which to iterate:
* var arr = [ 3000, 2500, 1000 ];
*
* // Define a callback which handles results:
* function done( error, bool ) {
*     if ( error ) {
*         throw error;
*     }
*     if ( bool ) {
*         console.log( 'At least one element passed.' );
*     } else {
*         console.log( 'No elements passed.' );
*     }
* }
*
* // Try to invoke the predicate for each element in `arr`:
* anyByAsync( arr, done );
*/
function factory( options, predicate ) {
	var opts;
	var err;
	var f;

	opts = {};
	if ( arguments.length > 1 ) {
		err = validate( opts, options );
		if ( err ) {
			throw err;
		}
		f = predicate;
	} else {
		f = options;
	}
	if ( !isFunction( f ) ) {
		throw new TypeError( format( 'invalid argument. Last argument must be a function. Value: `%s`.', f ) );
	}
	if ( opts.series ) {
		opts.limit = 1;
	} else if ( !opts.limit ) {
		opts.limit = PINF;
	}
	return anyByAsync;

	/**
	* Invokes a predicate function for each element in a collection.
	*
	* @private
	* @param {Collection} collection - input collection
	* @param {Callback} done - function to invoke upon completion
	* @throws {TypeError} first argument must be a collection
	* @throws {TypeError} last argument must be a function
	* @returns {void}
	*/
	function anyByAsync( collection, done ) {
		var status;

		if ( !isCollection( collection ) ) {
			throw new TypeError( format( 'invalid argument. First argument must be a collection. Value: `%s`.', collection ) );
		}
		if ( !isFunction( done ) ) {
			throw new TypeError( format( 'invalid argument. Last argument must be a function. Value: `%s`.', done ) );
		}
		status = {
			'status': 'pending',
			'ndone': 0,
			'nerrors': 0
		};

		// Wrap the predicate to track progress:
		limit( collection, opts, wrapper, clbk );

		return status;

		/**
		* Wraps the predicate function to track the number of completed invocations.
		*
		* @private
		* @param {*} value - collection element
		* @param {NonNegativeInteger} index - element index
		* @param {Callback} next - callback to invoke upon predicate completion
		* @returns {void}
		*/
		function wrapper( value, index, next ) {
			f( value, index, onResult );

			/**
			* Callback invoked upon predicate completion.
			*
			* @private
			* @param {(Error|null)} err - error argument
			* @param {*} result - predicate result
			* @returns {void}
			*/
			function onResult( err, result ) {
				status.ndone += 1;
				next( err, result );
			}
		}

		/**
		* Callback invoked upon completion of all predicate invocations.
		*
		* @private
		* @param {(Error|null)} error - error argument
		* @param {boolean} bool - whether at least one element passed the predicate
		* @returns {void}
		*/
		function clbk( error, bool ) {
			if ( error ) {
				status.status = 'fail';
				return done( error, false );
			}
			status.status = 'ok';
			done( null, bool );
		}
	}
}


// EXPORTS //

module.exports = factory;
